site.css:
.bd-site img, .bd-site video, .bd-site iframe {
max-width: 100%;
height: auto;
}
.bd-flow {
flex-direction: column;
}
.bd-col {
min-width: 0;
}
.bd-text.has-indent p + p {
margin-top: 15px;
}
.bd-embed iframe {
position: absolute;
inset: 0;
width: 100%;
height: 0;
border: 0;
}


.bd-rule {
align-self: center;
margin: 0;
border-top: 1px solid var(--bd-rule);
}


.bd-burger {
position: fixed;
top: 0;
right: var(--sm-pad);
padding: 0;
cursor: default;
color: inherit;
font-family: var(--bd-mono);
font-size: 15px;
line-height: 18px;
text-transform: none;
z-index: 2;
transition: transform var(--ly-pdur, var(--k-dur, var(--ly-dur))) var(--ly-ease);
}
.bd-burger.is-left {
right: auto;
left: 0;
}
.bd-burger svg {
display: block;
}


.bd-menu {
position: fixed;
max-height: calc(100vh - 110px);
overflow-y: auto;
display: flex;
justify-content: flex-start;
align-items: flex-end;
letter-spacing: 0em;
opacity: 0;
pointer-events: none;
}
.bd-menu-list {
flex: 1;
min-width: 0;
}
.bd-menu-head {
display: block;
font: inherit;
text-align: center;
}
.bd-menu-items {
display: none;
}
.bd-menu-group.is-open .bd-menu-items,
.bd-menu.is-open-all .bd-menu-items {
display: block;
}
.bd-menu-group.is-open .bd-menu-head {
text-decoration: underline;
text-underline-offset: 3px;
text-decoration-thickness: 1px;
}
.bd-menu.is-open-all .bd-menu-head {
text-decoration: none;
}
.bd-menu.is-flat .bd-menu-head {
display: none;
}
.bd-menu-group.is-plain .bd-menu-items {
display: block;
padding-left: var(--bd-wl);
}
.bd-menu.is-flat .bd-menu-items {
display: block;
}
.bd-menu.is-flat .bd-menu-group + .bd-menu-group {
margin-top: var(--bd-nav-lh);
}
.bd-menu-head: hover,
.bd-menu a:hover {
opacity: 0.4;
}
.bd-menu.is-cur-dim a.is-current {
opacity: 0.4;
}
.bd-menu.is-cur-underline a.is-current {
text-decoration: underline;
}
.bd-menu.is-cur-strike a.is-current {
text-decoration: line-through;
}
.bd-menu.is-cur-arrow a.is-current: :before {
content: "\2192\00a0";
}
.bd-menu-title {
flex: none;
margin-left: 0px;
white-space: nowrap;
}
.bd-menu.is-title-left {
flex-direction: row-reverse;
}
.bd-menu.is-title-left .bd-menu-title {
margin: 0 16px 0 0;
}
.bd-site: :before {
content: "";
position: relative;
}
.has-menu: :before {
opacity: 1;
}
.has-menu .bd-menu {
opacity: 1;
}
.has-menu .bd-main,
.has-menu .bd-pager {
opacity: var(--bd-nav-fade);
}


.bd-pager {
display: grid;
grid-template-columns: repeat(var(--cols), minmax(0, 1fr));
margin-top: 8px;
padding-top: max(0px, min(max(calc(100vh - 90vh), var(--k-pl, 0px)), calc(100vh - 48px)));
}
.bd-pager a {
display: block;
}
.bd-pager svg {
display: block;
}
.bd-pager-next {
grid-column: 3;
}


.bd-ptitle.is-al-center {
text-align: center;
}
.bd-ptitle.is-al-right {
text-align: right;
}


.bd-pin {
position: relative;
}
.bd-menubtn {
display: flex;
flex-wrap: wrap;
gap: 10px;
min-height: calc(100% - 0px - 90vh);
}
.bd-menubtn.is-al-center {
justify-content: center;
}
.bd-menubtn.is-al-end {
justify-content: flex-end;
}
.bd-menubtn.is-al-spread {
justify-content: space-between;
}
.bd-menubtn.is-brand-after .bd-mbrand {
order: 2;
}
.bd-menubtn.is-brand-above {
flex-direction: column;
}
.bd-menubtn.is-brand-above.is-al-center {
align-items: center;
}
.bd-menubtn.is-brand-above.is-al-end {
align-items: flex-end;
}
.bd-mbrand {
display: block;
}
.bd-mlist ul {
margin: 0;
list-style: none;
}
.bd-mlist a {
display: inline-block;
border-bottom: 0;
}
.bd-mlist.is-vertical li + li {
margin-top: var(--igap, 0px);
}
.bd-mlist.is-vertical .bd-mgroup + .bd-mgroup {
margin-top: var(--ggap, 20px);
}
.bd-mlist.is-horizontal,
.bd-mlist.is-horizontal ul {
display: flex;
}
.bd-mlist.is-horizontal {
gap: var(--ggap, 20px);
}
.bd-mlist.is-horizontal ul {
gap: var(--igap, 16px);
}
.bd-mlist.is-horizontal.has-heads .bd-mgroup {
display: flex;
}
.bd-mhead {
display: block;
margin-bottom: 50px;
}
.bd-mlist.is-horizontal .bd-mhead {
margin-bottom: 0;
}
.bd-mlist.is-hov-underline a: hover,
.bd-mlist.is-cur-underline a.is-current {
border-bottom-color: currentColor;
}
.bd-mlist.is-hov-dim a: hover,
.bd-mlist.is-cur-dim a.is-current {
opacity: 0.4;
}
.bd-mlist.is-cur-strike a.is-current {
text-decoration: line-through;
}
.bd-mlist.is-cur-arrow a.is-current: :before {
content: "\2192\00a0";
}
.bd-flow > .bd-menubtn.is-corner-right,
.bd-flow > .bd-menubtn.is-corner-left {
position: absolute;
}
.bd-flow > .bd-menubtn.is-corner-right {
right: 0;
}
.bd-flow > .bd-menubtn.is-corner-left {
left: 0;
}
.bd-burger.is-inline {
display: block;
}
.bd-pin .bd-el {
transition: opacity 0.25s ease;
}
.has-menu .bd-pin .bd-el: not(.bd-menubtn),
.has-menu .bd-mbrand {
opacity: var(--bd-nav-fade);
}
.bd-mbrand {
transition: opacity 0.25s ease;
}


.bd-posts {
display: grid;
column-gap: 30px;
row-gap: var(--prow, 40px);
}
.bd-posts.is-list {
grid-template-columns: minmax(0, 1fr);
}
.bd-posts.is-masonry {
display: block;
columns: var(--pcols, 3);
}
.bd-posts.is-masonry .bd-post {
break-inside: avoid;
}
.bd-post-txt {
min-height: var(--pminh, 0px);
}
.bd-post {
display: flex;
flex-direction: column;
}
.bd-post-img {
display: block;
}
.bd-posts.is-img-bottom .bd-post-img {
order: 2;
}
.bd-post img {
width: 100%;
object-fit: contain;
}
.bd-post-txt,
.bd-post-t,
.bd-post-d,
.bd-post-m,
.bd-post-x {
display: block;
}
.bd-post-d,
.bd-post-m,
.bd-post-x {
margin-top: var(--pmgap, 8px);
}
.bd-post.is-featured {
grid-column: 1 / -1;
column-span: all;
}
.bd-post.is-featured.is-f-side {
display: grid;
}
.bd-post.is-featured.is-f-side .bd-post-img {
margin: 0;
}
.bd-posts.is-hov-dim .bd-post: hover {
opacity: 0.6;
}
.bd-posts.is-hov-lift .bd-post: hover {
transform: translateY(-3px);
}


.bd-posts.is-zine .bd-post {
position: relative;
perspective: 900px;
}
.bd-post-cover {
display: contents;
}
.bd-posts.is-zine .bd-post-cover {
position: relative;
box-shadow: none;
transform-origin: 0 50%;
}
.bd-posts.is-zine.is-img-bottom .bd-post-cover .bd-post-img {
order: 2;
}
.bd-post-page {
position: absolute;
overflow: hidden;
}
.bd-posts.has-staples .bd-post-cover: :after {
bottom: 22%;
}
.bd-posts.is-zine a.bd-post: hover {
opacity: 1;
transform: translate3d(calc(var(--i) * -100% / var(--n)), 0, 0);
}
@media (hover: hover) and (min-width: 761px) {
.bd-ly .bd-ly-k.is-e-left.is-st-peek:hover:not(:has(a:hover)) {
--kx: calc((var(--k-peek) + var(--k-nudge)) - 100%);
}
}
.bd-posts.is-zine a.bd-post.is-open .bd-post-cover {
transform: rotateY(calc(var(--bd-g-open, 24deg) * -1));
}
.bd-posts.is-zine .bd-post-cover {
backface-visibility: hidden;
}
.bd-posts.is-zine a.bd-post.is-unfold {
z-index: 5;
}
.bd-posts.is-zine a.bd-post.is-unfold .bd-post-cover {
transform: rotateY(-170deg);
}
.bd-unfold {
position: fixed;
}
@view-transition {
navigation: auto;
}
.bd-posts.is-zine .bd-post.is-featured.is-f-side {
display: block;
}
.bd-posts.is-zine .bd-post.is-featured.is-f-side .bd-post-cover {
display: grid;
}


.bd-posts.is-trace .bd-post {
position: relative;
}
.bd-posts.is-trace .bd-post.is-featured.is-f-side {
display: block;
}
.bd-posts.is-trace .bd-post-img {
position: absolute;
}
.bd-posts.is-trace .bd-post-img img {
width: 100%;
filter: blur(var(--tp-imgblur, 0px)) var(--tp-tone, brightness(1));
}
.bd-post-paper {
position: absolute;
-webkit-backdrop-filter: blur(5px);
backdrop-filter: blur(5px);
}
.bd-posts.is-trace a.bd-post: hover {
opacity: 1;
}
@media (prefers-reduced-motion: reduce) {
.bd-post-paper {
transition: none;
}
.bd-posts.is-trace a.bd-post.is-open .bd-post-paper {
transform: var(--tp-tap, translate(0%, -62%)) rotate(var(--tp-tilt, 0deg));
}
}


.bd-postinfo-back {
margin-right: 0.6em;
text-decoration: none;
}
.bd-postinfo.is-al-center {
text-align: center;
}
.bd-postinfo.is-al-right {
text-align: right;
}
.bd-postinfo.is-al-spread {
