}
.bd-quote.has-line {
border-left: 1px solid currentColor;
}
.bd-quote p + p {
margin-top: var(--bd-lh);
}


.bd-toggle summary {
list-style: none;
}
.bd-toggle summary: :-webkit-details-marker {
display: none;
}
.bd-toggle.is-mark-plus summary: :before {
content: "+";
}
.bd-toggle.is-mark-plus[open] summary: :before {
content: "\2014";
}
.bd-toggle.is-mark-arrow summary: :before {
content: "\2192";
}
.bd-toggle.is-mark-arrow[open] summary: :before {
content: "\2193";
}
.bd-toggle ul {
margin: var(--bd-lh) 0 0;
}
.bd-toggle li + li {
margin-top: var(--tgap, 0px);
}


.bd-product {
display: block;
}
.bd-product img {
width: 100%;
}
.bd-product-t {
margin-top: 12px;
}
.bd-product.is-al-center {
text-align: center;
}
.bd-product.is-al-right {
text-align: right;
}
.bd-product-empty {
display: block;
}


.bd-pagerbar {
display: grid;
}
.bd-pagerbar.has-line {
padding-top: 14px;
}
.bd-pagerbar a {
display: block;
}
.bd-pagerbar svg {
display: block;
}
.bd-ix {
display: flex;
}
.bd-ix-a {
color: inherit;
}
.bd-ix.is-plain .bd-ix-a {
text-decoration: none;
}
.bd-ix-crumb {
opacity: var(--ix-dim);
}
.bd-ix-c {
color: inherit;
}
.bd-ix-c: hover {
text-decoration: underline;
}
.bd-pagerbar-next {
grid-column: 3;
}
.bd-pagerbar.is-text {
display: block;
}
.bd-pagerbar.is-text.is-al-center {
text-align: center;
}
.bd-pagerbar.is-text.is-al-right {
text-align: right;
}
.bd-pagerbar.is-text a {
display: inline;
}
.bd-pagerbar.is-text a + a {
margin-left: 2em;
}



.bd-gi {
--cols: 3;
--gut: 10px;
--rowh: 220px;
}
.bd-gi figure {
min-width: 0;
}
.bd-gi img {
width: 100%;
}
.bd-gi figcaption {
margin-top: 8px;
}
.bd-gallery.is-grid .bd-gi {
display: grid;
}
.bd-gallery.is-columns .bd-gi {
column-count: var(--cols);
}
.bd-gallery.is-columns .bd-gi figure {
break-inside: avoid;
}
.bd-gallery.is-justify .bd-gi {
display: flex;
}
.bd-gallery.is-justify .bd-gi: :after {
content: "";
flex-grow: 999;
}
.bd-gallery.is-justify .bd-gi figure {
flex-grow: var(--r);
flex-basis: calc(var(--r) * var(--rowh));
}
.bd-gallery.is-free .bd-gi {
